class Solution {

    /**
     * @param Integer[][] $grid
     * @return Integer
     */
    function cherryPickup($grid) {
        $rows = count($grid);
        $cols = count($grid[0]);

        // 3D DP array: dp[row][col1][col2]
        // max cherries collected with robots at positions col1 and col2 on row `row`.
        $dp = array_fill(0, $rows, []);
        for ($r = 0; $r < $rows; ++$r) {
            $dp[$r] = array_fill(0, $cols, array_fill(0, $cols, null));
        }

        // Recursive function with memoization
        // row: current row
        // c1: robot 1 column
        // c2: robot 2 column
        function dfs($row, $c1, $c2, $grid, $rows, $cols, &$dp) {
            if ($c1 < 0 || $c1 >= $cols || $c2 < 0 || $c2 >= $cols) return -INF;

            if ($row == $rows) return 0;

            if ($dp[$row][$c1][$c2] !== null) return $dp[$row][$c1][$c2];

            $result = $grid[$row][$c1];
            if ($c1 != $c2) $result += $grid[$row][$c2];

            $maxNext = -INF;
            for ($newC1 = $c1 - 1; $newC1 <= $c1 + 1; ++$newC1) {
                for ($newC2 = $c2 - 1; $newC2 <= $c2 + 1; ++$newC2) {
                    $maxNext = max($maxNext, dfs($row + 1, $newC1, $newC2, $grid, $rows, $cols, $dp));
                }
            }
            $result += $maxNext;
            $dp[$row][$c1][$c2] = $result;
            return $result;
        }

        return dfs(0, 0, $cols - 1, $grid, $rows, $cols, $dp);
    }
}

